<template>
  <section class="char-section">
    <span class="field-label">在场角色</span>
    <template v-if="characters.length">
      <div class="char-strip" role="tablist">
        <button
          v-for="character in characters"
          :key="character.key"
          type="button"
          class="char-chip"
          :class="{ active: character.key === selectedKey }"
          role="tab"
          :aria-selected="character.key === selectedKey"
          @click="selectedKey = character.key"
        >
          <span class="chip-avatar">
            <img v-if="character.portraitUrl" :src="character.portraitUrl" :alt="character.displayName" loading="lazy" />
            <span v-else class="chip-initial">{{ character.displayName.slice(0, 1) }}</span>
          </span>
          <span class="chip-main">
            <span class="chip-name">{{ character.displayName }}</span>
            <span class="chip-label">{{ character.label }}</span>
          </span>
        </button>
      </div>

      <div v-if="selected" class="char-card">
        <div class="card-portrait">
          <img v-if="selected.portraitUrl" :src="selected.portraitUrl" :alt="selected.displayName" loading="lazy" />
          <span v-else class="card-initial">{{ selected.displayName.slice(0, 1) }}</span>
        </div>
        <div class="card-body">
          <div class="card-title">
            <b class="card-name">{{ selected.displayName }}</b>
            <span class="card-label">{{ selected.label }}</span>
            <span v-if="selected.commitment === '恋人'" class="card-badge lover">恋人</span>
            <span v-else-if="selected.commitment === '仅朋友'" class="card-badge friend">仅朋友</span>
          </div>

          <div class="meter-row">
            <span class="meter-key">羁绊</span>
            <span class="meter-track"><span class="meter-fill bond" :style="{ width: `${selected.bond}%` }"></span></span>
            <span class="meter-num">{{ selected.bond }}</span>
          </div>
          <div class="meter-row">
            <span class="meter-key">恋爱</span>
            <span class="meter-track"><span class="meter-fill romance" :style="{ width: `${selected.romance}%` }"></span></span>
            <span class="meter-num">{{ selected.romance }}</span>
          </div>

          <div class="card-line">
            <span class="line-key">最近记得</span>
            <span class="line-value"> · {{ selected.memory || memoryPlaceholder }}</span>
          </div>
          <div class="card-line thought">
            <span class="line-key">没有说出口</span>
            <span class="line-value"> · {{ thoughtText }}</span>
          </div>

          <div class="card-outfit">
            <span class="line-key">服装</span>
            <span class="outfit-items">
              <span v-for="item in outfitItems" :key="item.label" class="outfit-item" :class="{ unknown: item.value === '未确认' }">
                {{ item.label }}·{{ item.value }}
              </span>
            </span>
          </div>
        </div>
      </div>
    </template>
    <span v-else class="char-empty">当前没有已识别且在场的关系对象</span>
  </section>
</template>

<script setup lang="ts">
import { MEMORY_EMPTY_PLACEHOLDER, THOUGHT_EMPTY_PLACEHOLDER, type PresentCharacterView } from '../utils';

const props = defineProps<{
  characters: PresentCharacterView[];
}>();

const selectedKey = ref('');

const selected = computed<PresentCharacterView | null>(() => {
  if (!props.characters.length) {
    return null;
  }
  return props.characters.find(character => character.key === selectedKey.value) ?? props.characters[0];
});

const memoryPlaceholder = MEMORY_EMPTY_PLACEHOLDER;

const thoughtText = computed(() =>
  selected.value?.innerThought ? `“${selected.value.innerThought}”` : THOUGHT_EMPTY_PLACEHOLDER,
);

const OUTFIT_LABELS: ReadonlyArray<readonly [keyof PresentCharacterView['outfit'], string]> = [
  ['outerwear', '外'],
  ['inner_layer', '内'],
  ['bottoms', '下装'],
  ['socks', '袜'],
  ['underwear', '贴身'],
  ['shoes', '鞋'],
];

const outfitItems = computed(() =>
  OUTFIT_LABELS.map(([key, label]) => ({ label, value: selected.value?.outfit[key] ?? '未确认' })),
);
</script>

